import sympy as sp
from sympy import symbols, QQ, reduced, groebner, poly

# Top-level setup: named object bindings that the witness expression may reference.
# We define variables for a polynomial ring over QQ.
# A valid counterexample can be constructed in the quotient ring QQ[x, y, z] / <x - x*y*z>.
x, y, z = symbols('x y z')

def in_ideal(expr, ideal_gens, gens):
    """Check if expr is in the ideal generated by ideal_gens in QQ[gens]."""
    try:
        _, rem = reduced(expr, ideal_gens, *gens, domain='QQ')
        return rem == 0
    except Exception:
        return False

def is_prime_ideal(ideal_gens, gens):
    """
    Heuristic to check if an ideal is prime in QQ[gens].
    For our specific counterexample, the quotient by the prime ideal 
    yields a free polynomial ring, meaning the Groebner basis consists 
    only of linear polynomials.
    """
    try:
        gb = groebner(ideal_gens, *gens, domain='QQ')
        if list(gb) == [sp.S(1)]:
            return False
        for g in gb:
            if g == 0:
                continue
            p = poly(g, *gens)
            if p.total_degree() > 1:
                return False
        return True
    except Exception:
        return False

def conditions(witness):
    try:
        gens = witness['gens']
        rels = witness['rels']
        a = witness['a']
        u = witness['u']
        factors = witness['factors']
        r = witness['r']
        N = witness['N']
        
        # H_1: a is a non-zero non-unit element of R
        a_nonzero = not in_ideal(a, rels, gens)
        a_nonunit = not in_ideal(sp.S(1), rels + [a], gens)
        H1 = a_nonzero and a_nonunit
        
        # H_2: a = u p_1^{k_1} ... p_m^{k_m} is a factorization into pairwise non-associate primes
        prod = u
        for p_elem, k in factors:
            prod *= p_elem**k
        a_eq_prod = in_ideal(a - prod, rels, gens)
        
        # Check if u is a unit
        u_is_unit = False
        if 'inv' in witness and u in witness['inv']:
            u_is_unit = in_ideal(u * witness['inv'][u] - 1, rels, gens)
        elif hasattr(u, 'is_Rational') and u.is_Rational and u != 0:
            u_is_unit = True
        elif isinstance(u, (int, float)) and u != 0:
            u_is_unit = True
            
        # Check if exponents are positive integers
        k_positive = all(isinstance(k, (int, sp.Integer)) and k > 0 for p_elem, k in factors)
        
        # Check if p_i are prime elements
        primes_ok = True
        for p_elem, k in factors:
            if not is_prime_ideal(rels + [p_elem], gens):
                primes_ok = False
                break
                
        # Check if p_i are pairwise non-associate
        non_assoc = True
        for i in range(len(factors)):
            for j in range(i + 1, len(factors)):
                pi = factors[i][0]
                pj = factors[j][0]
                # If they are associate, pi = c * pj for some unit c.
                # We check a few common rational units to ensure they are not trivially associate.
                for c in [-1, 1, 2, -2]:
                    if in_ideal(pi - c * pj, rels, gens):
                        non_assoc = False
                        
        H2 = a_eq_prod and u_is_unit and k_positive and primes_ok and non_assoc
        
        # ¬Q: The radical of <a> is NOT the principal ideal generated by p_1 ... p_m
        # The witness provides an element r and integer N such that r^N \in <a> but r \notin <p_1 ... p_m>
        P = sp.S(1)
        for p_elem, k in factors:
            P *= p_elem
            
        r_in_rad = in_ideal(r**N, rels + [a], gens)
        r_notin_P = not in_ideal(r, rels + [P], gens)
        
        neg_Q = r_in_rad and r_notin_P
        
        return [bool(H1), bool(H2), bool(neg_Q)]
    except Exception:
        return [False, False, False]

CONDITION_LABELS = [
    "H_1: a is a non-zero non-unit element of R",
    "H_2: a = u p_1^{k_1} \\cdots p_m^{k_m} is a factorization into pairwise non-associate primes",
    "¬Q: The radical of <a> is NOT the principal ideal generated by p_1 ... p_m"
]

N_HYP = 2
NEG_Q_INDEX = 2